CREATE TABLE request_products (
  request_id BIGINT NOT NULL REFERENCES requests(id),
  product_id BIGINT NOT NULL REFERENCES products(id),
  quantity   INT    NOT NULL CHECK (quantity > 0),
  PRIMARY KEY (request_id, product_id)
);

